import type { CollectionConfig } from 'payload'
import { revalidateSite } from '../lib/revalidate'
import { anyone, editors, reviewersField } from '../access/roles'

/** Nouns and pronouns. Case forms (8 vibhaktis × 3 numbers) are generated by Vidyut. */
export const Nouns: CollectionConfig = {
  slug: 'nouns',
  admin: { useAsTitle: 'display', group: 'Grammar', defaultColumns: ['display', 'meaning_en', 'gender', 'kind', 'status'] },
  hooks: { afterChange: [revalidateSite], afterDelete: [revalidateSite] },
  access: { read: anyone, create: editors, update: editors, delete: editors },
  fields: [
    { type: 'row', fields: [
      { name: 'display', type: 'text', required: true, admin: { width: '25%', description: 'e.g. विद्यालय, भवत्' } },
      { name: 'stemSlp1', type: 'text', required: true, admin: { width: '25%', description: 'Vidyut input (SLP1), e.g. vidyAlaya' } },
      { name: 'gender', type: 'select', required: true, options: [{ label: 'masculine', value: 'm' }, { label: 'feminine', value: 'f' }, { label: 'neuter', value: 'n' }], admin: { width: '20%' } },
      { name: 'kind', type: 'select', defaultValue: 'noun', options: [{ label: 'noun', value: 'noun' }, { label: 'pronoun', value: 'pronoun' }], admin: { width: '15%' } },
      { name: 'meaning_en', type: 'text', admin: { width: '15%' } },
    ] },
    { name: 'forms', type: 'json', admin: { description: '8 vibhaktis × 3 numbers, generated by Vidyut' } },
    { name: 'gloss', type: 'textarea' },
    { name: 'status', type: 'select', defaultValue: 'generated', access: { update: reviewersField }, options: [{ label: 'Generated', value: 'generated' }, { label: 'Approved', value: 'approved' }] },
  ],
}
